/**
 * 二分查找（迭代版）
 * @param arr    已按升序排序的数组
 * @param target 要查找的目标值
 * @returns 目标值的索引；不存在时返回 -1
 */
function binarySearch(arr: readonly number[], target: number): number {
  let lo = 0;
  let hi = arr.length - 1;

  while (lo <= hi) {
    // 这样写中点可避免 lo + hi 溢出（虽然 JS 数组下标基本不会溢出）
    const mid = lo + ((hi - lo) >> 1);
    const value = arr[mid];

    if (value === target) {
      return mid;
    } else if (value < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }

  return -1;
}
```

几点使用说明：

- 数组必须**已升序排序**，否则结果无意义。
- 若数组中有重复的 `target`，返回的是其中**任意一个**索引，不保证是最左/最右那个。需要第一个出现的位置时，把 `value === target` 时改成 `hi = mid - 1` 并记录答案（lower bound 写法）。
- 参数用 `readonly number[]`，所以 `number[]` 和只读数组都能传入，不会修改原数组。

